import qualified Data.ByteString.Char8 as BSChar
import qualified Data.Map              as Map

import Zocalo.Common.SecureToken(genSecureToken, SecureToken(tokenText))
import Zocalo.Common.SnapHelpers(
    asBool, asInt, asNanoID, asNonNeg, asToken, asUUID, Constraint(Constraint), failWith, free, notEmpty
  )

tests :: Test
tests =
  testGroup "Zocalo.Common.SnapHelpers" $
    [ testGroup "asNonNeg"
        [ testCase "accepts a decimal number" $ run asNonNeg "id" "42"  @?= Success (42 :: Word64)
        , testCase "accepts zero"             $ run asNonNeg "id" "0"   @?= Success (0 :: Word64)
        , testCase "rejects text"             $ run asNonNeg "id" "abc" @?= (Failure ["id"] :: Validation [Text] Word64)
        , testCase "rejects the empty string" $ run asNonNeg "id" ""    @?= (Failure ["id"] :: Validation [Text] Word64)
        , testCase "rejects fractions"        $ run asNonNeg "id" "4.5" @?= (Failure ["id"] :: Validation [Text] Word64)
        , testCase "rejects negative numbers" $ run asNonNeg "id" "-1"  @?= (Failure ["id"] :: Validation [Text] Word64)
        , testCase "rejects numbers too big for a Word64" $
            run asNonNeg "id" "18446744073709551616" @?= (Failure ["id"] :: Validation [Text] Word64)
        ]

    , testGroup "asInt"
        [ testCase "accepts negative numbers" $ run asInt "n" "-5" @?= Success (-5)
        , testCase "rejects trailing junk"    $ run asInt "n" "5x" @?= (Failure ["n"] :: Validation [Text] Int)
        ]

    , testGroup "asBool"
        [ testCase "accepts true"                  $ run asBool "flag" "true"  @?= Success True
        , testCase "accepts false"                 $ run asBool "flag" "false" @?= Success False
        , testCase "is case-insensitive"           $ run asBool "flag" "TRUE"  @?= Success True
        , testCase "rejects anything else"         $ run asBool "flag" "yes"   @?= Failure ["flag"]
        ]

    , testGroup "asNanoID"
        [ testCase "accepts a 21-character ID from the NanoID alphabet" $
            fmap unNanoID (run asNanoID "nano-id" validNano) @?= Success validNano
        , testCase "rejects an ID that is too short" $
            fmap unNanoID (run asNanoID "nano-id" "abc") @?= Failure ["nano-id"]
        , testCase "rejects an ID that is too long" $
            fmap unNanoID (run asNanoID "nano-id" (validNano <> "x")) @?= Failure ["nano-id"]
        , testCase "rejects a 21-character ID containing a character outside the alphabet" $
            fmap unNanoID (run asNanoID "nano-id" "V1StGXR8_Z5jdHi6B-my!") @?= Failure ["nano-id"]
        ]

    , testGroup "asUUID"
        [ testCase "accepts a canonical UUID" $
            fmap toText (run asUUID "bucket" uuidBS) @?= Success uuidText
        , testCase "rejects other text" $
            fmap toText (run asUUID "bucket" "not-a-uuid") @?= Failure ["bucket"]
        ]

    , testGroup "notEmpty / free"
        [ testCase "notEmpty names the offending parameter" $
            run notEmpty "email" "" @?= Failure ["email cannot be empty"]
        , testCase "notEmpty passes non-empty values through" $
            run notEmpty "email" "a@b.c" @?= Success "a@b.c"
        , testCase "free accepts the empty string" $
            run free "description" "" @?= Success ""
        ]

    , testGroup "asToken"
        [ testCase "accepts a freshly generated token" $ do
            token <- genSecureToken
            run asToken "token" (encodeUtf8 $ tokenText token) @?= Success token
        , testCase "rejects garbage" $
            run asToken "token" "garbage" @?= Failure ["token"]
        ]

    , testGroup "failWith" $
        map statusCase $
          [ (400, "Bad Request"), (401, "Unauthorized"), (403, "Forbidden"), (404, "Not Found")
          , (409, "Conflict"), (422, "Unprocessable Entity"), (500, "Internal Server Error")
          ]
    ]
  where
    validNano = "V1StGXR8_Z5jdHi6B-myT" :: ByteString
    uuidBS    = "123e4567-e89b-12d3-a456-426614174000" :: ByteString
    uuidText  = "123e4567-e89b-12d3-a456-426614174000" :: Text

    statusCase :: (Int, ByteString) -> Test
    statusCase (code, reason) = testCase (BSChar.unpack reason) $ statusOf code >>= (@?= (code, reason))

statusOf :: Int -> IO (Int, ByteString)
statusOf code =
  do
    response <- runHandler (get "/" Map.empty) $ failWith code $ writeText "message"
    return (rspStatus response, rspStatusReason response)

run :: Constraint t -> ByteString -> ByteString -> Validation [Text] t
run (Constraint f) = f
